package dev.pro8.homeview.direct;
import org.json.*;import java.io.*;import java.util.*;import android.util.AtomicFile;
/** Stage only selected originals; the journal restores them if the manifest was not committed. */
final class AlbumSourceDeletion {
 private final File root,trash;private final AtomicFile journal;private JSONArray staged=new JSONArray();
 AlbumSourceDeletion(File root,File privateFolder){this.root=root;trash=new File(root,".HomeView-trash");journal=new AtomicFile(new File(privateFolder,"source-delete-journal.json"));}
 private File source(String name)throws Exception{if(name.isEmpty()||name.contains("/")||name.contains("\\")||name.startsWith("."))throw new IOException("照片路径无效");File f=new File(root,name);if(!f.getCanonicalFile().equals(new File(root.getCanonicalFile(),name)))throw new IOException("照片路径无效");return f;}
 private File target(String name)throws Exception{if(!name.matches("import-[0-9a-f]{16}-[a-f0-9-]{36}\\.bak")||!trash.getCanonicalFile().equals(new File(root.getCanonicalFile(),".HomeView-trash")))throw new IOException("照片路径无效");return new File(trash,name);}
 private void save()throws Exception{FileOutputStream out=null;try{out=journal.startWrite();out.write(staged.toString().getBytes("UTF-8"));journal.finishWrite(out);}catch(Exception e){if(out!=null)journal.failWrite(out);throw e;}}
 void recover(JSONArray manifest)throws Exception{try(InputStream in=journal.openRead()){staged=new JSONArray(new String(NetEaseClient.read(in,256*1024),"UTF-8"));}catch(FileNotFoundException e){return;}Set<String> live=new HashSet<>();for(int i=0;i<manifest.length();i++)if(manifest.optJSONObject(i)!=null)live.add(manifest.getJSONObject(i).optString("id"));int pending=0;for(int i=0;i<staged.length();i++){JSONObject item=staged.getJSONObject(i);File from=source(item.getString("source")),to=target(item.getString("trash"));if(!to.exists())continue;if(live.contains(item.getString("id"))){if(from.exists()||!to.renameTo(from))pending++;}else if(!to.delete())pending++;}if(pending==0){journal.delete();staged=new JSONArray();}else throw new IOException("上次照片操作尚未恢复，请稍后重试");}
 void stage(JSONArray manifest,JSONArray ids)throws Exception{recover(manifest);Set<String> selected=new HashSet<>();for(int i=0;i<ids.length();i++)selected.add(ids.getString(i));staged=new JSONArray();for(int i=0;i<manifest.length();i++){JSONObject p=manifest.optJSONObject(i);if(p==null||!selected.contains(p.optString("id"))||p.optString("source").isEmpty())continue;File file=source(p.getString("source"));if(file.exists()&&!file.isFile())throw new IOException("照片文件无效");staged.put(new JSONObject().put("id",p.getString("id")).put("source",p.getString("source")).put("trash",p.getString("id")+"-"+UUID.randomUUID()+".bak"));}if(staged.length()==0)return;if(!trash.isDirectory()&&!trash.mkdirs())throw new IOException("暂时无法删除照片");target(staged.getJSONObject(0).getString("trash"));save();try{for(int i=0;i<staged.length();i++){JSONObject p=staged.getJSONObject(i);File file=source(p.getString("source"));if(file.exists()&&!file.renameTo(target(p.getString("trash"))))throw new IOException("暂时无法删除照片");}}catch(Exception e){recover(manifest);throw e;}}
 int finish(){int pending=0;for(int i=0;i<staged.length();i++)try{File file=target(staged.getJSONObject(i).getString("trash"));if(file.exists()&&!file.delete())pending++;}catch(Exception e){pending++;}if(pending==0){journal.delete();staged=new JSONArray();}return pending;}
}
